/* ScshOperPrfmncMapper.upsertList */ MERGE INTO PMOWN.TN_PM_SCSH_OPER_PRFMNC A USING (
SELECT #{item.totDt} AS TOT_DT, #{item.tmnlId} AS TMNL_ID, #{item.dptgtNo} AS DPTGT_NO, #{item.scshOperCntom} AS SCSH_OPER_CNTOM, #{item.scshObsrvnCntom} AS SCSH_OBSRVN_CNTOM, #{item.wtngPsgCnt} AS WTNG_PSG_CNT FROM DUAL
) B ON ( A.TOT_DT = B.TOT_DT AND A.TMNL_ID = B.TMNL_ID AND A.DPTGT_NO = B.DPTGT_NO ) WHEN MATCHED THEN UPDATE SET A.SCSH_OPER_CNTOM = B.SCSH_OPER_CNTOM, A.SCSH_OBSRVN_CNTOM = B.SCSH_OBSRVN_CNTOM, A.WTNG_PSG_CNT = B.WTNG_PSG_CNT, A.LAST_MDFR_ID = #{regId}, A.LAST_MDFR_IP_ADDR = #{regIp}, A.LAST_MDFCN_DT = SYSTIMESTAMP WHEN NOT MATCHED THEN INSERT (TOT_DT, TMNL_ID, DPTGT_NO, SCSH_OPER_CNTOM, SCSH_OBSRVN_CNTOM, WTNG_PSG_CNT, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT) VALUES (B.TOT_DT, B.TMNL_ID, B.DPTGT_NO, B.SCSH_OPER_CNTOM, B.SCSH_OBSRVN_CNTOM, B.WTNG_PSG_CNT, #{regId}, #{regIp}, SYSTIMESTAMP)
